 function openForm(r?:RecordItem){setEditing(r||null);setForm(r?Object.fromEntries(Object.entries(r.payload).filter(([k])=>k!=="interactions").map(([k,v])=>[k,String(v??"")])):{});setInteractionLog(Array.isArray(r?.payload.interactions)?r.payload.interactions:[]);setInteractionType("Ligação");setInteractionNote("");setInteractionDate(localDate());setInteractionOutcome("Em conversa");setInteractionNextAction("");setInteractionNextDate("");setModalOpen(true);}
  function openOutreach(record:RecordItem,channel="WhatsApp"){
  const p=record.payload||{};const company=String(p.name||"sua empresa");const person=String(p.contact_person||"");const greeting=person?"Olá, "+person+"!":"Olá, tudo bem?";
  const sector=p.sector?" do segmento de "+p.sector:"";const demand=Number(p.notebook_demand)>0?" para uma possível demanda de "+p.notebook_demand+" notebooks":"";
  const context=p.notes?String(p.notes).slice(0,220):"";
  const signature="Rodrigo | Soluções em locação de notebooks";
  let subject="Locação de notebooks"+(p.notebook_demand?" para "+company:"")+" | conversa rápida";
  let text="";
  if(channel==="E-mail"){text=greeting+"\n\nSou Rodrigo e estou entrando em contato porque trabalhamos com soluções de locação de notebooks para empresas"+sector+". Gostaria de entender se existe alguma necessidade atual ou prevista de equipamentos"+demand+".\n\nSe fizer sentido, posso conversar rapidamente para entender quantidade, configuração, prazo e modelo de atendimento. Assim consigo avaliar uma proposta adequada, sem compromisso.\n\nFico à disposição.\n"+signature;}
  else if(channel==="LinkedIn"){subject="";text=(person?"Olá, "+person+". ":"Olá! ")+"Encontrei a "+company+" e gostaria de conectar. Trabalho com soluções de locação de notebooks para empresas"+sector+". Se houver alguma demanda de equipamentos ou expansão de equipe, será um prazer trocar uma ideia.\n"+signature;}
  else{text=greeting+"\nSou Rodrigo. Trabalho com soluções de locação de notebooks para empresas"+sector+".\n\nQueria entender se a "+company+" tem alguma necessidade atual ou prevista de equipamentos"+demand+". Se fizer sentido, posso levantar uma opção adequada ao que vocês precisam.\n\nPodemos conversar?\n"+signature;}
  if(context)text+="\n\nContexto para personalizar antes do envio: "+context;
  setOutreach({recordId:record.id,company,channel,text,subject});setNotice("Abordagem preparada para revisão. Nenhuma mensagem foi enviada.");
 }
