 async function markAssetDelivered(asset:RecordItem){if(asset.payload.status!=="Reservado"||!asset.payload.contract_id){setNotice("Reserve o equipamento em um contrato antes de registrar a entrega.");return}if(!String(asset.payload.serial||"").trim()){setNotice("Número de série ausente. Corrija o cadastro antes de registrar a entrega.");return}const now=new Date().toISOString();const payload=appendAssetMovement({...asset.payload,status:"Alugado",assigned_at:now,delivered_at:now},{id:"MOV-"+Date.now().toString(36),type:"Entrega",from:"Reservado",to:"Alugado",at:now,by:String(user?.email||"Responsável não identificado"),serial:String(asset.payload.serial||""),contract_id:String(asset.payload.contract_id),contract_number:String(asset.payload.contract_number||"")});if(demo){setRows(prev=>prev.map(x=>x.id===asset.id?{...x,payload}:x));setNotice("Entrega marcada apenas na demonstração.");return}if(!supabase)return;setLoading(true);const {data,error}=await supabase.from("workspace_records").update({payload}).eq("id",asset.id).filter("payload->>status","eq","Reservado").filter("payload->>contract_id","eq",String(asset.payload.contract_id)).select().maybeSingle();if(error)setNotice(error.message);else if(!data)setNotice("A reserva mudou antes da entrega. Atualize o equipamento e confira o contrato.");else{setRows(prev=>prev.map(x=>x.id===asset.id?data as RecordItem:x));setNotice("Entrega registrada. Equipamento agora está alugado.")}setLoading(false)}
 async function registerAssetReturn(asset:RecordItem){
  if(asset.payload.status!=="Alugado"||!asset.payload.contract_id){setNotice("Este equipamento não possui locação ativa registrada.");return}
  const contract=rows.find(x=>x.module==="contracts"&&x.id===String(asset.payload.contract_id));
  if(!contract){setNotice("Contrato vinculado não encontrado. Não alterei o estoque.");return}
  if(String(contract.payload.type||"Locação")==="Venda"){setNotice("Contratos de venda não possuem fluxo de devolução.");return}
  if(!window.confirm("Confirma que o notebook "+String(asset.payload.serial||"")+" foi recebido fisicamente? O equipamento ficará bloqueado até concluir a inspeção."))return;
  const condition=window.prompt("Condição física do equipamento:\n1 = Sem avarias\n2 = Com avarias","1");
  if(condition!=="1"&&condition!=="2"){setNotice("Inspeção cancelada. O equipamento continua alugado.");return}
  const accessories=window.prompt("Acessórios recebidos (ex.: carregador, cabo, bolsa):")?.trim();
  if(accessories===undefined){setNotice("Inspeção cancelada. O equipamento continua alugado.");return}
  const functional=window.prompt("Teste funcional:\nDescreva inicialização, tela, teclado, portas e conectividade:")?.trim();
  if(functional===undefined){setNotice("Inspeção cancelada. O equipamento continua alugado.");return}
  const damaged=condition==="2";
  let diagnosis="",partsCost=0,laborCost=0;
  if(damaged){
   diagnosis=window.prompt("Descreva as avarias identificadas:")?.trim()||"Avaria identificada na inspeção de devolução.";
   const partsInput=window.prompt("Custo estimado de peças (R$):","0");
   if(partsInput===null){setNotice("Inspeção cancelada. O equipamento continua alugado.");return}
   const laborInput=window.prompt("Custo estimado de mão de obra (R$):","0");
   if(laborInput===null){setNotice("Inspeção cancelada. O equipamento continua alugado.");return}
   partsCost=Number(partsInput.replace(",", "."));laborCost=Number(laborInput.replace(",", "."));
   if(!Number.isFinite(partsCost)||partsCost<0||!Number.isFinite(laborCost)||laborCost<0){setNotice("Custos inválidos. Informe valores iguais ou maiores que zero.");return}
   if(!window.confirm("Registrar a avaria e abrir ordem de manutenção de R$ "+money(partsCost+laborCost)+"? O notebook ficará Em manutenção."))return;
  }else if(!window.confirm("Inspeção sem avarias. Confirmar liberação do notebook para Disponível?"))return;
  const now=new Date().toISOString(),inspectionId="RET-"+Date.now().toString(36).toUpperCase();
  const inspection={id:inspectionId,asset_id:asset.id,contract_id:contract.id,contract_number:String(contract.payload.number||""),inspected_at:now,inspected_by:String(user?.email||"Usuário"),condition:damaged?"Com avarias":"Sem avarias",accessories:accessories||"Não informado",functional_test:functional||"Não informado",diagnosis,parts_cost:partsCost,labor_cost:laborCost,total_cost:partsCost+laborCost};
  const maintenancePayload=damaged?{number:"MAN-"+localDate().replace(/-/g,"")+"-"+String(rows.filter(x=>x.module==="maintenance").length+1).padStart(3,"0"),asset_serial:String(asset.payload.serial||""),asset_tag:String(asset.payload.asset_tag||""),asset_model:[asset.payload.brand,asset.payload.model].filter(Boolean).join(" "),issue:"Avaria identificada na devolução do contrato "+String(contract.payload.number||""),diagnosis,technician:"",status:"Aberta",opened_at:localDate(),completed_at:"",parts_cost:partsCost,labor_cost:laborCost,total_cost:partsCost+laborCost,notes:"Ordem gerada na inspeção de devolução "+inspectionId+". Teste funcional: "+(functional||"Não informado")+". Acessórios: "+(accessories||"Não informado")+".",asset_id:asset.id,contract_id:contract.id,contract_number:String(contract.payload.number||""),return_inspection_id:inspectionId,previous_asset_status:"Em manutenção"}:null;
  const nextAsset=appendAssetMovement({...asset.payload,status:damaged?"Em manutenção":"Disponível",returned_at:now,last_contract_id:contract.id,last_contract_number:contract.payload.number||"",return_inspection:inspection,return_inspection_id:inspectionId,contract_id:null,contract_number:null,assigned_to:null,assigned_at:null,reserved_at:null,status_updated_at:now},{id:inspectionId,type:"Devolução recebida",from:"Alugado",to:damaged?"Em manutenção":"Disponível",at:now,by:String(user?.email||"Responsável não identificado"),serial:String(asset.payload.serial||""),contract_id:contract.id,contract_number:String(contract.payload.number||""),condition:damaged?"Com avarias":"Sem avarias",inspection_id:inspectionId});
  const returnedIds=new Set([...(Array.isArray(contract.payload.returned_asset_ids)?contract.payload.returned_asset_ids:[]),asset.id]);
  const contractAssetIds=Array.from(new Set([...(Array.isArray(contract.payload.inventory_asset_ids)?contract.payload.inventory_asset_ids:[]),...rows.filter(x=>x.module==="assets"&&(String(x.payload.contract_id||"")===contract.id||String(x.payload.last_contract_id||"")===contract.id)).map(x=>x.id)]));
  const expectedIds=contractAssetIds.length?contractAssetIds:[asset.id];
  const allReturned=expectedIds.every(id=>returnedIds.has(id));
  const previousReturnHistory=Array.isArray(contract.payload.return_inspections)?contract.payload.return_inspections:[];
  const nextContract={...contract.payload,return_status:allReturned?"Recebida":"Em conferência",returned_asset_ids:Array.from(returnedIds),return_inspections:[...previousReturnHistory,inspection],...(allReturned?{status:"Encerrado",closed_at:now,return_completed_at:now}:{})};
  if(demo){
   const maintenanceRecord=maintenancePayload?{id:"demo-maint-"+Date.now(),module:"maintenance" as ModuleKey,payload:maintenancePayload,created_at:now}:null;
   setRows(prev=>[...(maintenanceRecord?[maintenanceRecord]:[]),...prev.map(x=>x.id===asset.id?{...x,payload:nextAsset}:x).map(x=>x.id===contract.id?{...x,payload:nextContract}:x)]);
   setNotice(damaged?"Devolução inspecionada na demonstração. Notebook bloqueado em manutenção; ordem "+maintenancePayload!.number+" criada apenas localmente.":(allReturned?"Devolução inspecionada. Contrato encerrado na demonstração.":"Devolução inspecionada. Notebook liberado; aguardando os demais equipamentos do contrato."));
   return;
  }
  if(!supabase)return;
  setLoading(true);
  let maintenanceRecord:RecordItem|null=null;
  if(maintenancePayload){
   const inserted=await supabase.from("workspace_records").insert({module:"maintenance",payload:maintenancePayload}).select().single();
   if(inserted.error){setNotice("Não foi possível abrir a manutenção. A devolução não foi registrada: "+inserted.error.message);setLoading(false);return}
   maintenanceRecord=inserted.data as RecordItem;
  }
  const assetUpdate=await supabase.from("workspace_records").update({payload:nextAsset}).eq("id",asset.id).filter("payload->>status","eq","Alugado").filter("payload->>contract_id","eq",contract.id).select().maybeSingle();
  if(assetUpdate.error||!assetUpdate.data){
   if(maintenanceRecord)await supabase.from("workspace_records").delete().eq("id",maintenanceRecord.id);
   setNotice("O equipamento mudou durante a inspeção. Nenhuma devolução foi concluída; atualize os dados e tente novamente."+(assetUpdate.error?" "+assetUpdate.error.message:""));setLoading(false);return;
  }
  const contractUpdate=await supabase.from("workspace_records").update({payload:nextContract}).eq("id",contract.id).filter("payload->>status","eq",String(contract.payload.status||"Ativo")).select().maybeSingle();
  if(contractUpdate.error||!contractUpdate.data){
   await supabase.from("workspace_records").update({payload:asset.payload}).eq("id",asset.id);
   if(maintenanceRecord)await supabase.from("workspace_records").delete().eq("id",maintenanceRecord.id);
   setNotice("Não foi possível atualizar o contrato. A movimentação do notebook foi revertida; atualize a tela antes de tentar novamente."+(contractUpdate.error?" "+contractUpdate.error.message:""));setLoading(false);return;
  }
  setRows(prev=>[...(maintenanceRecord?[maintenanceRecord]:[]),...prev.map(x=>x.id===asset.id?assetUpdate.data as RecordItem:x.id===contract.id?contractUpdate.data as RecordItem:x)]);
  setNotice(damaged?"Devolução inspecionada. Notebook enviado para manutenção e ordem "+maintenancePayload!.number+" aberta. Não está disponível para nova locação.":(allReturned?"Todos os equipamentos foram recebidos e inspecionados. Contrato encerrado; notebook liberado no estoque.":"Inspeção concluída. Notebook liberado; o contrato permanece em conferência até os demais equipamentos serem devolvidos."));
  setLoading(false);
 }
 async function remove(r:RecordItem){if(r.module==="maintenance"&&!["Concluída","Cancelada"].includes(String(r.payload.status))){setNotice("Não é permitido excluir uma ordem de manutenção em aberto. Registre a conclusão ou o cancelamento para preservar o histórico.");return}if(r.module==="maintenance"){setNotice("Ordens de manutenção são parte do histórico operacional e não podem ser excluídas.");return}if(!confirm("Excluir este registro?"))return;if(demo){setRows(prev=>prev.filter(x=>x.id!==r.id));setNotice("Registro removido da demonstração.");return}if(!supabase)return;const {error}=await supabase.from("workspace_records").delete().eq("id",r.id);if(error)setNotice(error.message);else setRows(prev=>prev.filter(x=>x.id!==r.id))}
 async function generateMonthlyCharges(){
  if(loading)return;
  const competence=todayKey.slice(0,7);
  const contracts=rows.filter(r=>r.module==="contracts"&&r.payload.status==="Ativo"&&!String(r.payload.type||"Locação").includes("Venda"));
  if(contracts.length===0){setNotice("Não há contratos ativos de locação para gerar cobranças.");return}
  const existing=new Set(rows.filter(r=>r.module==="finance").map(r=>String(r.payload.charge_key||((r.payload.contract_id&&r.payload.competence)?r.payload.contract_id+"|"+r.payload.competence:""))).filter(Boolean));
  const candidates=contracts.filter(contract=>!existing.has(contract.id+"|"+competence));
  let created=0,skipped=contracts.length-candidates.length,missing=0;
  const newRows:RecordItem[]=[];
  setLoading(true);
  for(const contract of candidates){
   const p=contract.payload||{},startDate=String(p.start_date||"").slice(0,10);
   if(!/^\d{4}-\d{2}-\d{2}$/.test(startDate)||startDate>todayKey){missing++;continue}
   const [year,month]=competence.split("-").map(Number),startDay=Number(startDate.slice(8,10));
   const lastDay=new Date(year,month,0).getDate(),dueDate=year+"-"+String(month).padStart(2,"0")+"-"+String(Math.min(startDay,lastDay)).padStart(2,"0");
   const status=dueDate<todayKey?"Pendente":"Previsto";
   const payload={description:"Locação mensal · "+String(p.number||contract.id)+" · "+competence,company:String(p.company||""),kind:"Receita",category:"Locação",amount:Number(p.monthly_value||0),due_date:dueDate,paid_date:"",status,contract_id:contract.id,contract_number:String(p.number||""),competence,charge_key:contract.id+"|"+competence,generated_by:"VEYRION monthly billing",notes:"Cobrança prevista gerada a partir do contrato ativo. Confirme valor, vencimento e pagamento manualmente."};
   if(demo){newRows.push({id:"demo-charge-"+contract.id+"-"+competence,module:"finance",payload,created_at:new Date().toISOString()});created++;continue}
   if(!supabase){setNotice("Conecte o banco de dados ou use a demonstração para gerar cobranças.");setLoading(false);return}
   const {data,error}=await supabase.from("workspace_records").insert({module:"finance",payload}).select().single();
   if(error){if(error.code==="23505"){skipped++;continue}setRows(prev=>[...newRows,...prev]);setNotice("Foram criadas "+created+" cobrança(s), mas houve falha no próximo registro: "+error.message+". Execute novamente para continuar sem duplicar as já gravadas.");setLoading(false);return}
   newRows.push(data as RecordItem);created++;
  }
  if(newRows.length)setRows(prev=>[...newRows,...prev]);
  setNotice(created+" cobrança(s) gerada(s) para "+competence+"; "+skipped+" já existiam; "+missing+" contrato(s) sem data de início válida ou com início futuro foram ignorados. Nenhuma cobrança foi marcada como paga.");
  setLoading(false);
 }

 function prepareCsv(file:File){
  if(file.size>5*1024*1024){setNotice("Arquivo acima de 5 MB. Divida a planilha e tente novamente.");return}
  if(!["companies","contacts"].includes(module)){setNotice("Importação disponível para empresas e contatos.");return}
  const reader=new FileReader();reader.onload=()=>{
   try{
    const parsed=parseCsv(String(reader.result||""));
    const aliases:Record<string,string>={name:"name",company:module==="companies"?"name":"company",razaosocial:"name",empresa:module==="companies"?"name":"company",nome:"name",nomecompleto:"name",cnpj:"cnpj",funcionarios:"employees",numerodefuncionarios:"employees",qtdfuncionarios:"employees",headcount:"employees",employees:"employees",setor:"sector",segmento:"sector",site:"website",website:"website",cidade:"city",cidadeuf:"city",telefone:"phone",phone:"phone",origem:"source",fontereferencia:"source_detail",fontedapesquisa:"source_detail",referenciadapesquisa:"source_detail",datadapesquisa:"research_date",pesquisaem:"research_date",cargododecisor:"decision_maker_role",cargododecisorprocurado:"decision_maker_role",tipodefonte:"source_type",confiabilidadedafonte:"source_confidence",validacaodaempresa:"verification_status",statusdevalidacao:"verification_status",observacoes:"notes",email:"email",cargo:"role",departamento:"department",whatsapp:"whatsapp",poderdecisao:"decision_maker",notebooksestimados:"notebook_demand",notebooks:"notebook_demand",interesseemlocacao:"rental_interest",prioridadecomercial:"priority",prioridade:"priority",etapadaprospeccao:"prospect_stage",etapa:"prospect_stage",pessoadecontato:"contact_person",responsavelcontato:"contact_person",cargocontato:"contact_role",emailcontato:"contact_email",canalpreferido:"contact_channel",ultimocontato:"last_contact_at",proximaacaocomercial:"next_action",proximofollowup:"next_followup",followup:"next_followup"};
    const existing=new Set(rows.filter(x=>x.module===module).map(x=>String(x.payload[module==="companies"?"cnpj":"email"]||"").toLowerCase().replace(/[^a-z0-9]/g,"")).filter(Boolean));
    const seen=new Set<string>();
    const preview=parsed.records.map(values=>{
     const payload:Record<string,any>={};parsed.headers.forEach((h,i)=>{const key=aliases[h];if(key&&values[i])payload[key]=values[i]});
     if(module==="companies"&&payload.employees)payload.employees=Number(String(payload.employees).replace(/[^0-9]/g,""))||0;
     if(module==="companies"&&payload.notebook_demand)payload.notebook_demand=Number(String(payload.notebook_demand).replace(/[^0-9]/g,""))||0;
     const required=module==="companies"?["name","cnpj"]:["name","email"];
     let issue=required.some(k=>!String(payload[k]||"").trim())?"Campo obrigatório ausente": "";
     if(!issue&&module==="companies"&&String(payload.cnpj).replace(/\D/g,"").length!==14)issue="CNPJ deve conter 14 dígitos";
     if(!issue&&module==="contacts"&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(payload.email)))issue="E-mail inválido";
     const uniqueKey=String(payload[module==="companies"?"cnpj":"email"]||"").toLowerCase().replace(/[^a-z0-9]/g,"");
     if(!issue&&existing.has(uniqueKey))issue="Já existe no cadastro";
     else if(!issue&&seen.has(uniqueKey))issue="Duplicado no próprio arquivo";
     if(uniqueKey)seen.add(uniqueKey);
     return {payload,issue};
    });
    setCsvPreview(preview);setCsvName(file.name);setNotice("Prévia pronta: "+preview.filter(x=>!x.issue).length+" registros válidos; "+preview.filter(x=>x.issue).length+" ignorados.");
   }catch(e){setNotice(e instanceof Error?e.message:"Não foi possível ler o CSV.");setCsvPreview([])}
  };reader.onerror=()=>setNotice("Falha ao ler o arquivo.");reader.readAsText(file,"UTF-8");
 }
 async function confirmCsvImport(){
  const accepted=csvPreview.filter(x=>!x.issue);if(!accepted.length){setNotice("Não há linhas válidas para importar.");return}
  setImporting(true);
  if(demo){const now=new Date().toISOString();const added=accepted.map((x,i)=>({id:"csv-demo-"+Date.now()+"-"+i,module,payload:x.payload,created_at:now} as RecordItem));setRows(prev=>[...added,...prev]);setNotice(added.length+" registros adicionados somente à demonstração.");}
  else if(supabase){const {data,error}=await supabase.from("workspace_records").insert(accepted.map(x=>({module,payload:x.payload}))).select();if(error){setNotice("Importação não concluída: "+error.message);setImporting(false);return}setRows(prev=>[...((data||[]) as RecordItem[]),...prev]);setNotice((data||[]).length+" registros importados.");}
  else{setNotice("Configure o Supabase antes de importar.");setImporting(false);return}
  setCsvPreview([]);setCsvName("");if(csvInput.current)csvInput.current.value="";setImporting(false);
 }

 function exportCsv(){const list=module==="dashboard"?rows:visible;const keys=Array.from(new Set(list.flatMap(r=>Object.keys(r.payload))));const csv=[["Módulo",...keys].join(";"),...list.map(r=>[r.module,...keys.map(k=>String(r.payload[k]??"").replace(/;/g,","))].join(";"))].join("\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}));a.download="veyrion-export.csv";a.click();URL.revokeObjectURL(a.href)}
